@router.post("/marketing/dispatch-batch/{queue_job_id}/retry")
async def retry_failed_campaign_job(
    queue_job_id: str,
    payload: RetryOverridePayload,
    campaign_queue: CampaignQueue = Depends(get_campaign_queue),
    current_user: User = Depends(get_current_user)
):
    job = await campaign_queue.find_job(queue_job_id)
    if not job:
        raise HTTPException(status_code=404, detail="Campaign job not found")
    if job.organization_id != current_user.organization_id and not current_user.is_marketing_admin:
        raise HTTPException(status_code=403, detail="Forbidden: unauthorized access to campaign job")

    job.recipient_filter = payload.new_recipient_filter
    await campaign_queue.requeue(job)
    return {"status": "requeued", "job_id": queue_job_id}
